package com.retailflow.pos.reports;
import com.retailflow.pos.common.ApiResponse;import java.time.LocalDate;import java.util.Map;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/reports") @PreAuthorize("hasRole('OWNER')") public class ReportController{private final ReportService s;public ReportController(ReportService s){this.s=s;}@GetMapping("/pnl")public ApiResponse<?>pnl(@RequestParam@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to){return ApiResponse.ok(s.pnl(from,to));}@GetMapping("/gst-summary")public ApiResponse<?>gst(@RequestParam@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to){return ApiResponse.ok(s.gst(from,to));}@GetMapping("/balance-sheet")public ApiResponse<?>balance(@RequestParam(required=false)LocalDate asOf){return ApiResponse.ok(Map.of("asOf",asOf==null?LocalDate.now():asOf,"message","Derived from ledger balances"));}}
